import{_ as t,o as s,c as i,a5 as a}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Environnements d’exécution des plugins et limites de confiance","description":"","frontmatter":{"title":"Environnements d’exécution des plugins et limites de confiance","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"5f849b48d405ec96cf5d69ccfeb5e67b6628576288342b456b0998d3665ad99a","order":260},"headers":[],"relativePath":"fr/developer/plugins/runtimes.md","filePath":"fr/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),n={name:"fr/developer/plugins/runtimes.md"};function r(o,e,l,d,c,u){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">Environnements d’exécution des plugins et limites de confiance <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;Environnements d’exécution des plugins et limites de confiance {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Choisir un format exécutable dont les dépendances et la confiance correspondent à l’hôte. Lisez la <a href="./">présentation des plugins</a>, validez le manifeste contre la compilation réelle et examinez les restrictions propres aux cibles avant de charger du code. La compatibilité du protocole, celle de l’ABI native et les permissions accordées sont des vérifications indépendantes.</p><h2 id="choose-an-implemented-runtime" tabindex="-1">Choisir un environnement implémenté <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;Choisir un environnement implémenté {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environnement</th><th>Exécution</th><th>Confiance et portabilité</th></tr></thead><tbody><tr><td><code>native</code></td><td>ABI C via <code>libloading</code></td><td>Code de confiance dans le processus ; propre à la cible</td></tr><tr><td><code>process</code></td><td>Exécutable autonome, stdin/stdout encadrés</td><td>Isolation des plantages, permissions système ordinaires de l’utilisateur</td></tr><tr><td><code>napi-vm</code></td><td>JS compilé à l’avance sur QuickJS via <code>rquickjs</code></td><td>Effets hôte refusés par défaut ; les extensions natives facultatives changent la confiance</td></tr><tr><td><code>declarative</code></td><td>Descripteurs d’intégration validés</td><td>Aucun programme invité ; les effets passent par le courtier hôte</td></tr><tr><td><code>wasm</code></td><td>Emplacement d’exécution facultatif</td><td>Moteur général non activé dans les compilations normales</td></tr></tbody></table><p>L’ABI native v1 échange des octets sérialisés via une petite table C ; les conteneurs Rust, objets de trait et futures ne la traversent pas. Les bibliothèques natives restent chargées jusqu’à l’arrêt. L’encadrement des processus utilise une longueur u32 petit-boutiste suivie d’octets JSON, pas des RPC de contrôle délimitées par lignes. Gardez les sorties diagnostiques hors du canal stdout encadré.</p><h2 id="understand-quickjs-compatibility" tabindex="-1">Comprendre la compatibilité QuickJS <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;Comprendre la compatibilité QuickJS {#understand-quickjs-compatibility}&quot;">​</a></h2><p>Le nom de manifeste <code>napi-vm</code> reste stable, mais les anciennes affirmations sur un interpréteur distinct en Rust pur sont historiques. Les programmes invités reçoivent les variables globales de compatibilité documentées, pas un environnement Node complet. <code>napi_get_uv_event_loop</code> n’est pas pris en charge. Les extensions natives <code>.node</code> utilisent un parcours dans le processus volontairement de confiance, limité par liste autorisée et vérifié par SHA-256 ; le nom du runtime JavaScript ne les rend pas sûres.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>Utilisez des tests ciblés du chargeur lorsqu’une fixture complète d’extension native nécessiterait des outils de plateforme indisponibles.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>L’analyse du manifeste rejette les combinaisons protocole/ABI non prises en charge avant le chargement. Android autorise QuickJS portable et les entrées de processus Android/Bionic valides, mais rejette les bibliothèques dynamiques natives et extensions <code>.node</code>. Une ressource de bureau Linux/glibc n’est pas un plugin processus Android.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Redémarrez un hôte privé après remplacement d’une bibliothèque native. Si le démarrage dépasse le délai et devient incertain, le gestionnaire peut conserver l’identité du worker et bloquer le remplacement ; ne contournez pas cet état en déclarant l’arrêt réussi. Les tampons d’événements sont bornés et la livraison peut signaler du retard ; l’émission au démarrage n’est pas une file durable. L’<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">implémentation du chargeur</a> définit le moteur actuel et le comportement du cycle de vie.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Les limites actuelles sont 512 MiB de mémoire QuickJS, pile 2 MiB, budget d’interruption par appel, trames 16 MiB et jusqu’à 128 appels en file par instance. Elles ne garantissent pas l’annulation des effets. Un processus en timeout est terminé/retiré ; un appel natif ne peut pas être tué sûrement et son instance reste retenue. Des effets OS peuvent déjà avoir eu lieu. Examinez résultat original et cycle de vie avant remplacement/reprise. Les addons <code>.node</code> fiables utilisent les privilèges du processus hôte hors du périmètre JS.</p>`,16)])])}const h=t(n,[["render",r]]);export{m as __pageData,h as default};
